import{j as e,H as o}from"./main.Dvg-4Rkk.js";import{F as r,f as d,k as c,l as p,m,n as u,o as g,p as b,q as f,r as y,s as j,t as x,u as w,v,w as T}from"./index.es.BmnXUpy9.chunk.js";import{f as k,a as S,b as C}from"./index.es.Dcs01aiz.chunk.js";import{T as t}from"./index.CPOa-GGt.chunk.js";import{I as a}from"./Icon.BZ_xSH4A.chunk.js";const M=o.global,A=o.api,i="MDposit",h=[{id:"introduction",title:"Introduction",body:e.jsxs(e.Fragment,{children:["Welcome to the ",i," documentation page.",e.jsx("br",{}),e.jsx("br",{}),i," is an open platform designed to provide web access to atomistic molecular dynamics (MD) simulations. The aim of this initiative is to ease and promote data sharing along the world-wide scientific community in order to contribute in research.",e.jsx("br",{}),e.jsx("br",{}),"For any doubt please contact"," ",e.jsx("a",{href:"mailto:daniel.beltran@irbbarcelona.org",children:"daniel.beltran@irbbarcelona.org"})]}),children:[{id:"context",header:"Context",body:e.jsxs(e.Fragment,{children:[i," is part of the"," ",e.jsx(t,{name:"MDDB",url:"https://mddbr.eu/"})," project. The platform is being developed from the"," ",e.jsx(t,{name:"Molecular Modeling and Bioinformatics",url:"http://mmb.irbbarcelona.org/www/"})," ","group at"," ",e.jsx(t,{name:"IRB Barcelona",url:"https://www.irbbarcelona.org/en"})," ","in collaboration with the"," ",e.jsx(t,{name:"Barcelona Supercomputing Center",url:"https://www.bsc.es/"}),". This project has been also developed under the scope of"," ",e.jsx(t,{name:"BioExcel",url:"https://bioexcel.eu/"})," center. The original project started as a branch of the MoDEL-CNS project, which was supported by the"," ",e.jsx(t,{name:"Human Brain Project",url:"https://www.humanbrainproject.eu/en/"}),"."]})}]},{id:"data",title:"Data",body:e.jsx(e.Fragment,{children:"Here is summarized the data life cycle, since we receive raw data from the providers until the final data is made available to the consumers."}),children:[{id:"source",header:"Data source",body:e.jsxs(e.Fragment,{children:["Simulations in ",i," proceed from several different sources. Some simulations are downloaded from global repsoitories such as"," ",e.jsx(t,{name:"MolSSI",url:"https://covid.molssi.org/"}),". In addition, the platform contains simulations sent from research groups. In case you want to share your simulations with"," ",i," please"," ",e.jsx(t,{name:"contact us",url:"http://mmb.irbbarcelona.org/www/locationmap"}),"."]})},{id:"processing",header:"Data processing",body:e.jsxs(e.Fragment,{children:["Before a simulation is uploaded to the ",i," database, it is processed through a workflow. This workflow standarizes data format and then analyzes the simulation in order to upload the analysis results also to the database. Some important aspects of this processing are detailed here.",e.jsx("br",{}),e.jsx("br",{}),e.jsx("b",{children:"Quality control"}),e.jsx("br",{}),e.jsx("br",{}),e.jsx("br",{}),e.jsx("b",{children:"Interactions"}),e.jsx("br",{}),'Interactions are set manually by the author or a technician. Each interaction is defined by a name and two "interacting agents". Each agent is defined by a name and an atom selection. After the interaction has been defined, residues in the interface are automatically found by using a distance cutoff of 5 Ångstroms (Å) for up to 100 frames along the trajectory (i.e. if two residues from different agents are closer than the cutoff in at least one frame then they both are considered interface residues). Then all interaction analyses are run for each of the interactions (e.g. hydrogen bonds).',e.jsx("br",{}),e.jsx("br",{}),e.jsx("b",{children:"Mapping"}),e.jsx("br",{}),"Protein aminoacid sequences are mapped against their corresponding reference sequences. (e.g. spike proteins are mapped against the"," ",e.jsx(t,{name:"Wuhan-Hu-1/2019",url:"https://www.ncbi.nlm.nih.gov/nuccore/MN908947"})," ","reference sequence). This allows to number residues in the structure according to the widely known reference numeration (which may not match the original topology numeration). In addition, this mapping allows to show residue-related bibliographic data for residues in the structure (e.g. epitopes)."]})},{id:"storage",header:"Data storage",body:e.jsxs(e.Fragment,{children:[M?e.jsx(e.Fragment,{children:"This is the global node"}):e.jsx(e.Fragment,{children:"This is a federated node"}),e.jsx("br",{}),e.jsx("br",{}),e.jsx("b",{children:"The global node"}),e.jsx("br",{}),'The global node stores an "index" of every simulation in every federated node. It also stores all the relevant metadata to support queries along all nodes, including reference data such as PDB or UniProt data. The global node does not duplicate trajectory data or analysis results, but it redirects to the corresponding federated node when asked for any of those.',e.jsx("br",{}),e.jsx("br",{}),e.jsx("b",{children:"The federated nodes"}),e.jsx("br",{}),"Federated nodes store the actual data, including the simulation metadata, trajectory coordinates, analysis results and additional files. Data is stored in a"," ",e.jsx(t,{name:"MongoDB",url:"https://www.mongodb.com/"})," database.",e.jsx("br",{}),e.jsx("br",{}),e.jsx("b",{children:"Trajectory data"}),e.jsx("br",{}),"Atom positions along the trajectory are stored as files where each coordinate is a 32 bit float in Little Endian binary and there are no separators between coordinates, atoms or frames. The file has not headers or footers either. This format is size efficient and allows to retrieve specific frame and atom coordinates without the need of reading the file. The byte position of any range of coordinates may be easily calculated beforehand. Data is stored through Mongo's GridFS.",e.jsx("br",{}),e.jsx("br",{}),e.jsx("b",{children:"Metadata and analyses"}),e.jsx("br",{}),"Both metadata and analysis results are stored as plain Mongo documents.",e.jsx("br",{}),e.jsx("br",{}),e.jsx("b",{children:"Additional files"}),e.jsx("br",{}),"Any other downloadable file is stored through the Mongo's GridFS."]})},{id:"available",header:"Data availability",body:e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"The federated nodes"}),e.jsx("br",{}),'Federated nodes may upload or delete data at their discretion. In addition, data may be hidden or made visible and every simulations may be flagged as "published" or "not published". Every simulation in the node will have its own identifier (ID). Simulation IDs in a single federated node are garanteed to be unique. However these IDs are not persistent and they may dissapear when data is deleted. Fedrated IDs are not to follow a coherent format. They may be customized and diverse.',e.jsx("br",{}),e.jsx("br",{}),e.jsx("b",{children:"The global node"}),e.jsx("br",{}),'The global node feeds on all federated nodes periodically. If a simulation has been flagged as "published" by its node then the global node will issue a new persistent ID for it and the simulation will become available in production. Persistent IDs will remain traceable even if data is removed from the source federated node. Persistent IDs will always have the following format: MD-XXXXXX, where "X" are alphanumeric upper characters.']})},{id:"retrieval",header:"Data retrieval",body:e.jsxs(e.Fragment,{children:["Data in this node may be retrieved through a"," ",e.jsx(t,{name:"REST API",url:A}),".",e.jsx("br",{}),e.jsx("br",{}),e.jsx("b",{children:"Trajectory data"}),e.jsx("br",{}),"Trajectory data may be retrieved in the source format or it may be exported to other formats. The API has a built in parser to mdcrd format. In order to export to other formats (xtc, trr) the API has implemented ",e.jsx(t,{name:"Chemfiles",id:"chemfiles"}),".",e.jsx("br",{}),e.jsx("br",{}),e.jsx("b",{children:"Metadata and analyses"}),e.jsx("br",{}),"Metadata and analyses are retrieved in json format.",e.jsx("br",{}),e.jsx("br",{}),e.jsx("b",{children:"Additional files"}),e.jsx("br",{}),"Any other downloadable file is retrieved in it original format."]})},{id:"summary",header:"Data summary and statistics",body:e.jsxs(e.Fragment,{children:["A summary of current data is available in the ",e.jsx(t,{name:"statistics page",page:"statistics"}),"."]})}]},{id:"analyses",title:"Analyses",children:[{id:"rmsds",header:"RMSDs",body:e.jsxs(e.Fragment,{children:["RMSDs page includes both ",e.jsx(t,{name:"RMSD",id:"rmsd"})," and"," ",e.jsx(t,{name:"TM score",id:"tm-score"})," analyses together."]}),page:e.jsxs(e.Fragment,{children:["This is the RMSDs analysis.",e.jsx("br",{}),e.jsx("br",{}),"This page includes both RMSD and TM score analyses together. Each analysis has been run against the first frame and against the average structure of the whole trajectory. Use tabs above the first table to switch between those analyses.",e.jsx("br",{}),e.jsx("br",{}),"RMSD analyses are run over different atom selections. By default, it is computed for protein atoms, nucleics acid atoms and all atoms in every defined ligand. Some projects may contain additional RMSD analyses for custom atom selections. First table displays the mean, standard deviation and maximum values of each atoms selection in Ångstroms (Å). In addition, there is a checkbox next to each atom selection name which allows to hide or show data in the graph below.",e.jsx("br",{}),e.jsx("br",{}),"Graph displays the RMSD/TM score values along the trajectory. RMSD is computed for every frame in the trajectory, but frames are grouped in consecutive blocks and only a summary of each block is displayed: the line stands for the block mean value and the colored area around it stands for the block standard deviation. The horizontal axis stands for the trajectory time in nanoseconds. The vertical axis may stand for the RMSD in Ångstroms (Å) or the TM score. The graph is"," ",e.jsx("span",{style:{color:"lightGreen"},children:"interactive"}),". Use the mouse wheel to zoom in a specific region. Click and hold at any point in the graph to drag it left or right. Hover any point in the graph to show the corresponding RMSD/TM score value and the range of frames in the block. Click any point in the graph to open a"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","showing the structure conformation at the frame with the maximum RMSD in the selected block. This is useful to inspect sudden jumps in the RMSD, which may happen in a few specific frames only. When several atom selections are displayed, the frame is picked from the selection whose maximum stands out the most. Hide the other selections in the table above to inspect a specific selection."]})},{id:"rmsd",header:"RMSD",body:e.jsxs(e.Fragment,{children:["RMSD analyses have been run against the first frame and against the average structure of the whole trajectory. The RMSD is computed for every frame in the trajectory. Then frames are grouped in consecutive blocks and the mean, standard deviation and maximum values of each block are stored, together with the frame where the maximum value is found. Atoms under periodic boundary conditions (PBC) are ignored in this analysis.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by ",e.jsx(t,{name:"Gromacs",id:"gromacs"}),"."]})},{id:"tm-score",header:"TM score",body:e.jsxs(e.Fragment,{children:["TM score analyses are run against the first frame and against the average structure of the whole trajectory. TM score analyses are run over alpha carbon atoms. The TM score value of the structure is stored on up to 100 frames along the trajectory. Only atoms not in periodic boundary conditions (PBC) are measured in this analysis.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by the"," ",e.jsx(t,{name:"tmscoring",url:"https://pypi.org/project/tmscoring/"})," ","python module. Click"," ",e.jsx(t,{name:"here",url:"https://zhanglab.ccmb.med.umich.edu/TM-score/"})," ","to learn more about TM score."]})},{id:"rmsd-perres",header:"RMSD per residue",body:e.jsxs(e.Fragment,{children:["The RMSD (Root Mean Squared Deviation) per residue analysis computes the RMSD between each residue in its original conformation (first frame) and its conformations in up to 200 frames along the trajectory. Membrane residues are excluded from this analysis since they are prone to jump across boundaries thus having high RMSD values. Only atoms not in periodic boundary conditions (PBC) are measured in this analysis.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by ",e.jsx(t,{name:"PyTraj",id:"pytraj"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the RMSD per residue analysis.",e.jsx("br",{}),e.jsx("br",{}),"RMSD values are calculated against the trajectory first frame. First panel is the residue selector. Residues are divided by chains. Chains are delimited by their titles and residues may be expanded or compressed for each chain independently. Each residue is represented by a single letter. The 'X' letter represents non-standard residues (i.e. not natural aminoacids). Residues sequence is split and numerated every 10 residues. Each residue is coloured according to its RMSD value. The color scale ranges from white (lowest values) to red (highest values).",e.jsx("span",{style:{color:"lightGreen"},children:" Click any residue "})," to display its RMSD along the trajectory and highlight its atoms on the NGL viewer. Multiple residues may be selected at the same time. In this case, each selected residue is tagged with a different color.",e.jsx("br",{}),e.jsx("br",{}),"Graph at bottom left displays the RMSD of selected residues. Y axis represents the RMSD value in Ångstroms (Å) while X axis represents the simulation time in nanoseconds (ns). The graph is"," ",e.jsx("span",{style:{color:"lightGreen"},children:"interactive"}),". Use the mouse wheel to zoom in a specific region. Click and hold at any point in the graph to drag it left or right. Hover any point in the graph to show the corresponding RMSD and time values. Click any point in the graph to make the NGL viewer represent the corresponding time frame.",e.jsx("br",{}),e.jsx("br",{}),e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","at the right bottom shows the trajectory. The structure is coloured according to residue RMSD values. The color scale ranges from white (lowest values) to red (highest values)."]})},{id:"rmsd-pairwise",header:"RMSD pairwise",body:e.jsxs(e.Fragment,{children:["The RMSD (Root Mean Squared Deviation) pairwise analysis computes RMSD between 200 pairs of frames along the trajectory. The analysis is done for the whole structure and for the interface residues in each interaction. Note that this analysis is performed only with alpha carbon atoms for performance reasons. Only atoms not in periodic boundary conditions (PBC) are measured in this analysis.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by ",e.jsx(t,{name:"PyTraj",id:"pytraj"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the RMSD pairwise analysis.",e.jsx("br",{}),e.jsx("br",{}),"A RMSD pairwise analysis is run for all residues (Overall), which is the deafult displayed analysis. However, another analysis is run for every defined interaction, where interface residues are considered. Use 'Residues selector' over the heatmap to select the analysis to be displayed.",e.jsx("br",{}),e.jsx("br",{}),"Heatmap represents the RMSD between each pair of frames along the trajectory. Both horizontal and vertical axes stand for frame numbers. The color stands for the RMSD value and it ranges from blue (low) to red (high). The legend below shows the corresponding values in Ångstroms (Å). The heatmap is"," ",e.jsx("span",{style:{color:"lightGreen"},children:"interactive"}),". Hover any cell to show a tooltip with the pair of corresponding frames and the RMSD value between them. Click any cell on the heatmap to open a"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","displaying both corresponding frames overlapped. The horizontal axis frame is coloured in red while the vertical axis frame is coloured in blue."]})},{id:"rgyr",header:"Radius of gyration",body:e.jsxs(e.Fragment,{children:["The radius of gyration analysis computes the radius of gyration of a molecule and the radii of gyration about the x-, y- and z-axes, as a function of time. The atoms are explicitly mass weighted. Only atoms not in periodic boundary conditions (PBC) are measured in this analysis. This analysis is performed over up to 5000 frames along the trajectory.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by ",e.jsx(t,{name:"Gromacs",id:"gromacs"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the Radius of gyration (Rgyr) analysis.",e.jsx("br",{}),e.jsx("br",{}),"There are four data sets: One three-dimensional (blue) and three single-dimensional radius. These are RgyrX (yellow), RgyrY (green) and RgyrZ (red). Statistics table includes data label, mean and standard deviation values for the overall Rgyr and each dimension. Values are in Ångstroms (Å).",e.jsx("br",{}),e.jsx("br",{}),"Graph displays the 4 Rgyr dataset values for each frame along the trajectory. Data is displayed (more opaque lines) alongside corresponding mean value (light horizontal line) and mean ± 1 standard deviation (lighter horizontal bands). The horizontal axis stands for the trajectory time in nanoseconds. The vertical axis stands for the Rgyr in Ångstroms (Å). The graph is"," ",e.jsx("span",{style:{color:"lightGreen"},children:"interactive"}),". Use the mouse wheel to zoom in a specific region. Click and hold at any point in the graph to drag it left or right. Hover any point in the graph to show the corresponding Rgyr and time values. Click any point in the graph to open a"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","showing the structure conformation at the selected time frame."]})},{id:"fluctuation",header:"Fluctuation",body:e.jsxs(e.Fragment,{children:["The fluctuation analysis computes the RMSF (Root Mean Square Fluctuation, i.e. standard deviation) of atomic positions along the whole trajectory after fitting to the first frame. Only atoms not in periodic boundary conditions (PBC) are measured in this analysis.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by ",e.jsx(t,{name:"Gromacs",id:"gromacs"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the atoms fluctuation analysis",e.jsx("br",{}),e.jsx("br",{}),"Statistics table includes fluctuation data label, mean and standard deviation. Values are in Ångstroms (Å).",e.jsx("br",{}),e.jsx("br",{}),"Graph below represents the fluctuation of each atom. Data is displayed (more opaque lines) alongside corresponding mean value (light horizontal line) and mean ± 1 standard deviation (lighter horizontal bands). The horizontal axis stands for the atoms numeration. The vertical axis stands for the flucutation in Ångstroms (Å). The graph is"," ",e.jsx("span",{style:{color:"lightGreen"},children:"interactive"}),". Use the mouse wheel to zoom in a specific region. Click and hold at any point in the graph to drag it left or right. Click any point in the graph to open a"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","showing the trajectory with selected atoms and their residues highlighted. Multiple atoms may be selected at the same time. Hover any point in the graph to show the highlighted atom in the viewer if it is already opened. The 'Clear selection' button below removes all graph selections and the viewer."]})},{id:"pca",header:"PCA",body:e.jsxs(e.Fragment,{children:["PCA (Principal Component Analysis) calculates and diagonalizes the (mass-weighted) covariance matrix from up to 2000 frames along the trajectory in order to obtain a set of orthogonal eigenvectors and its associated eigenvalues. Then a set of conformations (20 frames) are projected into the eigenvectors 2D space (e.g. Principal Component 1 and Principal Component 2) for the relevant eigenvectors (the ones with explained variance greater than 1%). Note that PCA analysis is performed only with backbone atoms for performance reasons. Only atoms not in periodic boundary conditions (PBC) are measured in this analysis.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by ",e.jsx(t,{name:"scikit-learn",id:"sklearn"}),".",e.jsx("br",{}),"Projections are generated with the aid of ",e.jsx(t,{name:"MDtraj",id:"mdtraj"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the PCA analysis.",e.jsx("br",{}),e.jsx("br",{}),"The blue bars in the starting graph stand for the eigenvalue, according to the left axis, and the explained variance, according to the right axis, of any PCA projection. The yellow line stands for the accounting explained variance, according to the right axis.",e.jsx("br",{}),e.jsx("br",{}),"The graph is interactive. Hover any bar with the mouse to show the exact eigenvalue and explained variance values. Click one or more bars to select or deselect them. The exact eigenvalue and explained variance values of each selected bar will be permanently shown below the graph. Also, the accounting explained variance of all selected bars is displayed further below.",e.jsx("br",{}),e.jsx("br",{}),"In case one bar is selected then a"," ",e.jsx(t,{name:"viewer",id:"ngl-viewer"})," will appear with the corresponding pca projection trajectory or eigen vector. Use the mouse inside the NGL window to move, rotate or zoom the camera. You can get topology data of any atom by placing the mouse over it. Also some controls ara available under the NGL viewer in order to play/pause the trajectory, go fullscreen or change the viewer settings. Place the mouse over any button to show a summary title. Note that not all protein atoms are represented but only the backbone.",e.jsx("br",{}),e.jsx("br",{}),"In case two bars are selected then the PCA projections along the chosen eigenvectors are shown. The color stands for the trajectory time. Click any point in the graph to open a new"," ",e.jsx(t,{name:"viewer",id:"ngl-viewer"})," showing the selected frame.",e.jsx("br",{}),e.jsx("br",{}),"In case more than 2 bars are selected then just the sum of their explained variance is shown."]})},{id:"sasa",header:"Solvent accessible surface",body:e.jsxs(e.Fragment,{children:["The Solvent Accessible Surface (SAS) analysis computes the area of contact between the solvent and each residue for up to 200 frames along the trajectory. Then values are divided by the number of atoms on each residue in order to get the SAS per atom per residue values. Only atoms not in periodic boundary conditions (PBC) are measured in this analysis.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by ",e.jsx(t,{name:"Gromacs",id:"gromacs"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the Solvent accessible surface analysis.",e.jsx("br",{}),e.jsx("br",{}),"First panel is the residue selector. Residues are divided by chains. Chains are delimited by their titles and residues may be expanded or compressed for each chain independently. Each residue is represented by a single letter. The 'X' letter represents non-standard residues (i.e. not natural aminoacids). Residues sequence is split and numerated every 10 residues. Each residue is coloured according to its SAS per atom value. The color scale ranges from white (lowest values) to red (highest values).",e.jsx("span",{style:{color:"lightGreen"},children:" Click any residue "})," to display its SAS per atom along the trajectory and highlight its atoms on the NGL viewer. Multiple residues may be selected at the same time. In this case, each selected residue is tagged with a different color.",e.jsx("br",{}),e.jsx("br",{}),"Graph at bottom left displays the SAS per atom of selected residues. Y axis represents the surface in squared Ångstroms (Å",e.jsx("sup",{children:2}),") while X axis represents the simulation time in nanoseconds (ns). The graph is ",e.jsx("span",{style:{color:"lightGreen"},children:"interactive"}),". Use the mouse wheel to zoom in a specific region. Click and hold at any point in the graph to drag it left or right. Hover any point in the graph to show the corresponding SAS and time values. Click any point in the graph to make the NGL viewer represent the corresponding time frame.",e.jsx("br",{}),e.jsx("br",{}),e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","at the right bottom shows the trajectory. The structure is coloured according to residue SAS per atom values. The color scale ranges from white (lowest values) to red (highest values)."]})},{id:"dist-perres",header:"Distance per residue",body:e.jsxs(e.Fragment,{children:["The distance per residue analysis computes distance between each pair of residues in each interaction interface for up to 200 frames along the trajectory. Distance is calculated using the geometric center of every residue. Distance average and standard deviation are calculated.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by ",e.jsx(t,{name:"PyTraj",id:"pytraj"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the Distance per residue analysis.",e.jsx("br",{}),e.jsx("br",{}),"A distance per residue analysis is run for each interaction, recording the mean and standard deviation of distances along the trajectory between each residue in each different interaction agent. Use this panel to select which interaction residues are displayed in the heatmap below. Only the interaction interface residues are shown by default, but also all residues may be displayed (i.e. all residues of each interacting agent).",e.jsx("br",{}),e.jsx("br",{}),"Heatmap represents the mean distance between the geometric center of selected residues from different interacting agents along the trajectory. Both horizontal and vertical axes stand for residue numbers. The color stands for the distance and it ranges from blue (far) to red (close). The legend below shows the corresponding values in Ångstroms. Use tabs over the heatmap to switch between the mean distance and the standard deviation. The heatmap is"," ",e.jsx("span",{style:{color:"lightGreen"},children:"interactive"}),". Hover any cell to show a tooltip with the pair of corresponding residues and the mean distance / standard deviation value between them. Click any cell on the heatmap to open a"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","displaying the trajectory with both corresponding residues highlighted."]})},{id:"electrostatic",header:"Electrostatic potential surface",body:e.jsxs(e.Fragment,{children:["The Electrostatic potential surface is not an analysis but a representation. Interface residues from both interacting agents are displayed. One of them is represented as a surface which is colored according to the atomic charges. In case atomic charges are missing the color is the"," ",e.jsx("a",{href:"http://nglviewer.org/",target:"_blank",rel:"noreferrer noopener",children:"NGL"})," ",'"electrostatic" default color scheme. The other interface is represented in balls+sticks and colored by elements. Both representation systems are switchable.']}),page:e.jsxs(e.Fragment,{children:["This is the electrostatic potential surface representation.",e.jsx("br",{}),e.jsx("br",{}),"Use the 'Interaction' selector to change the represented interaction in the"," ",e.jsx("a",{href:"http://nglviewer.org/",target:"_blank",rel:"noreferrer noopener",children:"NGL viewer"})," ","below. By default, the interface residues from one of the interacting agents is represented in electrostatic surface mode and the interface residues from the other agent is represented in balls and sticks coloured by element. The rest of the structure is represented in low opacity grey cartoon. Both the 'surfaced' and the 'sticked' agent names are shown next to the interaction selector. The representation of both agent interfaces may be switched with the toggle button between their names.",e.jsx("br",{}),e.jsx("br",{}),"Note that trajectory is not loaded in this context because the surface representation is too heavy to be updated dinamically. The first frame is loaded instead."]})},{id:"hbonds",header:"Hydrogen bonds",body:e.jsxs(e.Fragment,{children:["Hydrogen bonds analysis computes whenever a hydrogen bond is formed for up to 200 frames along the trajectory. Only hydrogen bonds between different interacting agents are observed. An acceptor and a donor atom are considered to form a hydrogen bond when the distance between them is lower than 3 Ångstroms and the 'acceptor - hydrogen - donor' atoms angle is higher than 135 degrees.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by ",e.jsx(t,{name:"PyTraj",id:"pytraj"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the hydrogen bonds analysis.",e.jsx("br",{}),e.jsx("br",{}),"A hydrogen bonds analysis is run for each defined interaction. Use the 'Interaction' selector to switch between these analyses.",e.jsx("br",{}),e.jsx("br",{}),'Table below lists hydrogen bonds. First three columns display the first interacting agent atoms, hydrogen atoms and the second interacting agent atoms respectively. Interacting agent atoms are labeled with the format "chain : residue number (residue name) . atom name" while hydrogen atoms are labeled with the atom name only. Hydrogen atoms are also represented with a long hyphen pointing to the donor atom, which may be either the first or the second interacting agent atom. The fourth column represents the hydrogen bond status along the observed trajectory frames from the begining (left) to the end (right). Blue regions stand for frames where the hydrogen bond happened while ligth grey regions stand for frames where it did not. Hydrogen bonds are grouped by both acceptor and donor atoms. Note that some bonds may be repeated in two different groups for this reason. Bond groups are sorted from most to least stability in the table.',e.jsx("br",{}),e.jsx("br",{}),"You can ",e.jsx("span",{style:{color:"lightGreen"},children:"click"})," in the colored bar in order to open a"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","showing the trajectory with both the acceptor and the donor atoms from the selected bond and their residues highlighted. In addition, the distance between these atoms and the 'acceptor - hydrogen - donor' atoms angle are represented."]})},{id:"energies",header:"Energies",body:e.jsxs(e.Fragment,{children:["Energies analysis computes the Electrostatic and Van der Waals forces and the sum of both values for all residues from each pair of interacting agents for up to 100 frames along the trajectory. Energy averages per residue are calculated for the overall, start and end of the trajectory. The start and end averages are calculated from the first 20% and last 20% of frames of the previous subset. Energies are calculated for each atom individually and then added by residues. In case of strong bonds (e.g. covalent bonds) between two interacting agents the strong bond itself will be ignored. Both atoms implicated in the bond will be excluded from the analysis. Strong bonds are guessed by atoms distance and radius, using the"," ",e.jsx(t,{name:"VMD",id:"vmd"})," logic.",e.jsx("br",{}),e.jsx("br",{}),"This analysis requires atomic charges to work and thus it will not be run when charges are not provided by authors.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by ",e.jsx(t,{name:"CMIP",id:"cmip"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the energies analysis.",e.jsx("br",{}),e.jsx("br",{}),"Use the interaction selector in the top of the page to select which interaction energies analysis is to be displayed. The displayed energy values and residues in the table and graphs below correspond to the 'Host' when interacting with the 'Guest'. In order to switch which interacting agent is the Host and which is the Guest use the toggle button next to the interaction selector.",e.jsx("br",{}),e.jsx("br",{}),"The overall energies summatory table shows the sum of all residue energies together for each energy (Electrostatic, Van der Waals and both) and each set (overall, initial and final).",e.jsx("br",{}),e.jsx("br",{}),"Graphs represent from top to bottom the electrostatic potential, the Van der Waals forces and the sum of both values per each residue respectively. Energy averages are calculated for the overall, start and end of the trajectory. These averages are represented in black, red and blue colors respectively. Horizontal axes stand for the host residues. Residue numeration is according to the reference topology. Residues with no reference use the data source numeration and are marked with a '*' symbol. Vertical axes stand for the residue potential in kcal/mol. Strong bonds between the host and the guest are marked in light orange color.",e.jsx("br",{}),e.jsx("br",{}),"Graphs are ",e.jsx("span",{style:{color:"lightGreen"},children:"interactive"}),". Use the mouse wheel to zoom in a specific region. Click and hold at any point in the graph to drag it left or right. Click any point in the graph to open a"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","displaying the trajectory with the corresponding highlighted residue."]})},{id:"pockets",header:"Pockets",body:e.jsxs(e.Fragment,{children:["Pockets analysis searches for cavities along the trajectory. First, a preliminar analysis is run in order to generate a three-dimensional frequency grid of 1 Ångstrom resolution. Grid points are considered only if they have an isovalue of 0.5 or greater. Then pockets are defined as groups of connected grid points with a minimum width of 3 points (i.e. 3 Ångstroms) in all three dimensions. Finally, the first 10 biggest pockets are analyzed individually by computing their volume for up to 100 frames along the trajectory. Atoms surrounding each cavitiy are also found. This analysis is not run in systems with periodic boundary conditions (PBC) provisionally for technical reasons.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by"," ",e.jsx(t,{name:"MDpocket",id:"mdpocket"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the pockets analysis.",e.jsx("br",{}),e.jsx("br",{}),"Only the ten biggest pockets are analyzed and shown here. Left table lists these pockets and their average volume along the trajectory. Hover any pocket row to highlight the pocket region in the viewer. Click any pocket checkbox to show the pocket permanently in the viewer and display its volume thorugh the trajectory in the graph. Toggle the overall pockets checkbox to show/hidde all pocket regions.",e.jsx("br",{}),e.jsx("br",{}),"Right"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","shows the selected pockets. Pockets are labeled according to their table name. The represented pockets surfaces are average surfaces and they do not change when the time / frame in the viewer is modified. Pockets are colored grey by default. Hovered pocket is highlighted yellow and each selected pocket is colored with a unique color corresponding to table colors. In addition, the surface of atoms which form the selected pockets is also represented and it is coloured grey. Pocket surface atoms are always the same along the trajectory.",e.jsx("br",{}),e.jsx("br",{}),"Graph below displays the selected pocket volumes along the trajectory. Each line is colored corresponding to both table and viewer colors. Left axis represents the pocket volume in cubic Ångstroms (Å",e.jsx("sup",{children:3}),"). Horizontal axis represents trajectory frames. The graph is"," ",e.jsx("span",{style:{color:"lightGreen"},children:"interactive"}),". Click any point to represent the corresponding frame in the viewer."]})},{id:"mutations",header:"Mutations",body:e.jsxs(e.Fragment,{children:["Entropies for each residue were obtained from the"," ",e.jsx("a",{href:"https://nextstrain.org/ncov/global",target:"_blank",rel:"noreferrer noopener",children:"Nextstrain"})," ","web page, which relies on the"," ",e.jsx("a",{href:"https://www.gisaid.org/",target:"_blank",rel:"noreferrer noopener",children:"GISAID"})," ","database. The reference sequence is"," ",e.jsx("a",{href:"https://www.ncbi.nlm.nih.gov/nuccore/MN908947",target:"_blank",rel:"noreferrer noopener",children:"Wuhan-Hu-1/2019"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the mutations analysis.",e.jsx("br",{}),e.jsx("br",{}),"The"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","below represents the entropy of each residue in a logarithmic color scale which ranges from grey (low entropy) to red (high entropy). Use the residue selector to highlight a specific residue and focus it with the camera."]})},{id:"epitopes",header:"Epitopes",body:e.jsxs(e.Fragment,{children:["Epitopes were mined from the"," ",e.jsx("a",{href:"https://www.rcsb.org/",target:"_blank",rel:"noreferrer noopener",children:"PDB"})," ",". A systematic search was performed with the parameters 'Source Organism Taxonomy Name' as 'SARS-CoV-2' + 'Homo sapiens' and 'Additional Structure Keywords' contains phrase 'antibody'. Last search was performed on December 2021 with more than 260 results. For each structure, SARS-CoV-2 interface residues with the antibody were found by using a distance cutoff of 5 Ångstroms between atoms. In addition, the Solvent Accessible Surface (SAS) was calculated for these residues alone (removing all other residues). This value is considered as the 100% exposition SAS and then used for reference."]}),page:e.jsxs(e.Fragment,{children:["This is the epitopes viewer.",e.jsx("br",{}),e.jsx("br",{}),"Epitopes present in the structure are listed in the left table. Left column lists the PDB code of the corresponding SARS-CoV-2 + human antibody structure. Right column includes the average Solvent Accessible Surface (SAS) of the epitope in Å² and its exposition in percent along the trajectory for each chain. Partial epitopes are marked with a '*' character since the exposure is an estimation made from this part of the epitope.",e.jsx("br",{}),e.jsx("br",{}),"Epitopes can be represented in the"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","at right, over the overall structure in low opacity black color. Click in the overall 'Epitopes' checkbox to show the region covered by all epitopes together in purple color. Hover any epitope to highlight its residues in yellow color. Click on any epitope checkbox to display its residues in a specific color and its exposition percent along the trajectory in the graph below. Lines of each epitope are represented with a different color. The line of each chain is represented with a different dash pattern. Click anywhere on the graph to change the viewer trajectory frame.",e.jsx("br",{}),e.jsx("br",{}),"Several epitopes may be selected in order to compare them. Note that if overlapping epitopes are selected then epitopes above in the list will eclipse epitopes below in the viewer."]})},{id:"populations",header:"Populations",body:e.jsx(e.Fragment,{children:"Populations data is provided by the authors of the Markov state model ensemble. Data includes the MSM-derived equilibrium population for each frame in the ensemble."}),page:e.jsxs(e.Fragment,{children:["This is the populations viewer.",e.jsx("br",{}),e.jsx("br",{}),"All populations over a 0.1% cutoff are listed in the left table in decreasing order. Each population includes also its frame in the ensemble. Click any row in the table to display the corresponding frame in the"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","at right."]})},{id:"allostery",header:"Allostery",body:e.jsxs(e.Fragment,{children:["Allosteric communication network analysis using"," ",e.jsx("a",{href:"https://github.com/yasamankarami/compass",target:"_blank",rel:"noreferrer noopener",children:"ComPASS"})," ","(Communication Pathway Analysis within Protein-Nucleic Acid Complexes). This analysis is calculated using up to 1000 frames along the trajectory.",e.jsx("br",{}),e.jsx("br",{}),"Residues are the nodes of a graph and links between them are weighted according to how strongly they communicate along the trajectory. Link weights come from an adjacency matrix which integrates three residue pairwise metrics: the generalized correlation of residue motions (using CA atoms in proteins and C5' atoms in nucleic acids), the frequency of interactions between residues (non-bonded contacts, salt bridges and hydrogen bonds) and the communication propensity, which is derived from the variance of the distance between residues along the trajectory. Only residues within a distance cutoff are linked in the graph.",e.jsx("br",{}),e.jsx("br",{}),"Several graph theory properties are then calculated over the network. Allosteric hotspots are the top 5% most important residues in the network according to their centrality (betweenness, closeness and degree). Communities are clusters of residues which are densely connected among themselves, and they are found using the Leiden algorithm. Cliques are fully connected subgraphs, i.e. groups of residues where every residue is linked to every other residue in the group."]}),page:e.jsxs(e.Fragment,{children:["This is the allosteric communication network.",e.jsx("br",{}),e.jsx("br",{}),"Links between residues are displayed in the"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"molecular viewer"}),". Stronger links are thicker and more opaque. Link strengths range from 0% to 100%. Hover any link to see the residues it connects and its strength.",e.jsx("br",{}),e.jsx("br",{}),"Use the selector to paint hotspots, cliques or communities over the structure, or to color links by their strength instead. Click any region in the legend to highlight its residues.",e.jsx("br",{}),e.jsx("br",{}),"Use the sliders to hide links which are weaker than a minimum strength, or links between residues of the same chain which are closer in sequence than a minimum step. For instance, a minimum step of 2 hides links between consecutive residues, which are expected to be strongly coupled anyway since they are covalently bonded."]})},{id:"chemical-shifts",header:"Chemical shifts",body:e.jsxs(e.Fragment,{children:["Protein NMR chemical shifts predicted along the trajectory (up to 1000 frames) using"," ",e.jsx("a",{href:"https://github.com/roitberg-group/legolas",target:"_blank",rel:"noreferrer noopener",children:"LEGOLAS"}),", a machine learning model built over TorchANI which predicts chemical shifts from protein structures. Chemical shifts are predicted for backbone nitrogen (N), amide hydrogen (H), alpha carbon (CA) and hydrogen (HA), beta carbon (CB) and carbonyl carbon (C) atoms.",e.jsx("br",{}),e.jsx("br",{}),"For every atom, the average chemical shift and its standard deviation along the trajectory are provided. LEGOLAS predictions come from an ensemble of 5 models, and the standard deviation between models is a measure of the prediction confidence. The mean of this deviation along the trajectory (csmdv) is also provided for every atom, where higher values stand for less reliable predictions.",e.jsx("br",{}),e.jsx("br",{}),"The trajectory is also split in 10 consecutive frame ranges and the average chemical shift and its standard deviation are provided for every atom in every range, so changes in the chemical shift along the trajectory can be followed."]}),page:e.jsxs(e.Fragment,{children:["These are the predicted chemical shifts.",e.jsx("br",{}),e.jsx("br",{}),"Use the selector to choose which atom name (CA, CB, C, HA, H or N) is displayed in the top graph. Dots represent the average chemical shift of every atom and vertical bars represent its standard deviation along the trajectory. Dots are colored according to the reliability of their prediction, from blue (reliable) to red (not reliable).",e.jsx("br",{}),e.jsx("br",{}),"Click any atom in the top graph to highlight it in the"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"molecular viewer"})," ","and see how its chemical shift changes along the trajectory in the bottom graph. Atoms may also be selected by clicking them in the viewer. The line represents the average chemical shift in every frame range and the shaded area represents its standard deviation.",e.jsx("br",{}),e.jsx("br",{}),"The viewer loads one frame for every frame range, which is the central frame of the range. Click any frame range in the bottom graph to display its frame in the viewer."]})},{id:"clusters",header:"Clusters",body:e.jsxs(e.Fragment,{children:["The clusters analysis groups the trajectory frames in conformational states. One analysis is run for the overall structure, using alpha carbons (CA) in proteins and C5' atoms in nucleic acids (or all heavy atoms if there are none), and one more for every interaction, using the heavy atoms of its interface residues. Atoms under periodic boundary conditions (PBC) are excluded from this analysis.",e.jsx("br",{}),e.jsx("br",{}),"Frames are superposed to the first frame over the selected atoms, and their coordinates are reduced with PCA (Principal Component Analysis), keeping as many components as needed to explain 95% of the variance. When frames are a time series with a known time step, TICA (Time-lagged Independent Component Analysis) is then applied with a lag time of 1 ns. TICA finds the slowest motions, so clusters stand for long-lived states rather than for wide but fast fluctuations. TICA is not applied to ensembles, nor to trajectories too short to observe repeated transitions between states (shorter than 10 times the time the slowest motion takes to relax). At most 10 components are passed to the clustering.",e.jsx("br",{}),e.jsx("br",{}),"Frames are clustered with HDBSCAN, a density-based algorithm which finds the number of clusters by itself. A cluster must hold at least 1% of the frames (and at least 3 frames). Frames out of any dense region are left as noise: noise frames between two different clusters are transition frames, while noise frames which leave a cluster and come back to it are an excursion. If no dense region is found then all frames form a single cluster. Transitions between clusters are counted along the trajectory, skipping noise frames.",e.jsx("br",{}),e.jsx("br",{}),"The most representative frame of each cluster is the closest one to the cluster center, and the least representative frame is the farthest one. The screenshot of each cluster shows its most representative frame, with the least representative one behind as a transparent silhouette.",e.jsx("br",{}),e.jsx("br",{}),"Analyses run with older versions of the workflow clustered up to 1000 frames according to the RMSD between them, adjusting the RMSD cutoff until about 20 clusters were found. These analyses have no excursions nor transition frames.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by ",e.jsx(t,{name:"scikit-learn",id:"sklearn"})," and"," ",e.jsx(t,{name:"MDtraj",id:"mdtraj"}),". Screenshots are made with"," ",e.jsx(t,{name:"VMD",id:"vmd"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the clusters analysis.",e.jsx("br",{}),e.jsx("br",{}),"Use the selector over the graph to switch between the overall clusters and the clusters of each interaction interface.",e.jsx("br",{}),e.jsx("br",{}),"Each node in the graph is a cluster, i.e. a conformational state, and shows a screenshot of its most representative frame. The transparent silhouette behind it, if any, is its least representative frame. Node areas are proportional to the number of frames in the cluster. Arrows stand for transitions between clusters, and loops stand for excursions, where the trajectory leaves a cluster and comes back to it without reaching another cluster. The more times a transition or an excursion happens, the wider and darker its arrow.",e.jsx("br",{}),e.jsx("br",{}),"The graph is ",e.jsx("span",{style:{color:"lightGreen"},children:"interactive"}),". Hover any node to show its population among the displayed clusters and its most representative frame, and to fade the arrows which are not connected to it. Hover any arrow or loop to show how many times it happens. Click any node to open a ",e.jsx(t,{name:"viewer",id:"ngl-viewer"})," showing its most representative frame. Click any arrow or loop to open a viewer playing the frames of the first time it happened. Transitions with no frames in between, and those from analyses run with older versions of the workflow, can not be clicked.",e.jsx("br",{}),e.jsx("br",{}),"Use the sliders below the graph to change how many clusters are displayed, the most populated first, and how many transitions, the most frequent first. Use the switch to show or hide the excursion loops. Represented transitions is the percent of all transitions between clusters which is drawn by the displayed arrows."]})},{id:"markov",header:"Markov Graph",body:e.jsx(e.Fragment,{children:"Equilibirum populations are provided by the authors of the Markov State Model ensemble. RMSD matrix reflecting the RMSD value between each pair of states is precalculated. Data includes the 20 most populated states only."}),page:e.jsxs(e.Fragment,{children:["This is the Markov graph.",e.jsx("br",{}),e.jsx("br",{}),"States with the highest equilibrium population in the Markov State Model are displayed. Each state is represented by a node with a screenshot of the corresponding structure. Node radii are proportional to their state equilibrium populations. Links between states represent their RMSD similarity. Thickness of each link is an interpolation between the lower (more thick) and higher (less thick) RMSD values among the displayed links. Hover any node to plot its state equilibrium population and corresponding ensemble frame. Click any node to show the state structure in the ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:" molecular viewer"}),". Use the sliders below to change the number of nodes or links to be displayed in the graph."]})},{id:"density",header:"Density",body:e.jsxs(e.Fragment,{children:["Density analysis using"," ",e.jsx("a",{href:"https://amber-md.github.io/pytraj/latest/analysis.html#pytraj.density",target:"_blank",rel:"noreferrer noopener",children:"PyTraj density"})," "," function, which calculates the density of a system by slicing the z axis every 0.25 Å. The density can be calculated by number (N), mass (Da) or electron (Ne – q).",e.jsx("br",{}),e.jsx("br",{}),"The cpptraj density command calculates linear density along a specified coordinate (e.g., Da/Å along the z-axis). To obtain volumetric density divide the linear density output by the area of the cross-section formed by the other two dimensions."]}),page:e.jsxs(e.Fragment,{children:["Linear density for each chain over the z axis over slices of 0.25 Å. Three types of density are represented in the graph: number of atoms (N), mass (Da) and electron (e⁻).",e.jsx("br",{}),e.jsx("br",{}),"For the headgroups, we choose the most charged atom of each lipid residue.",e.jsx("br",{}),e.jsx("br",{}),"Note that trajectories are normally fitted so the protein stay in the center.",e.jsx("br",{}),e.jsx("br",{}),"The plot is ",e.jsx("span",{style:{color:"lightGreen"},children:"interactive"}),". Click on any point to open a "," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," "," displaying a plane at the place where the density has being calculated."]})},{id:"thickness",header:"Thickness",body:e.jsxs(e.Fragment,{children:["Membrane thickness analysis performed with the"," ",e.jsx("a",{href:"https://lipyphilic.readthedocs.io/en/latest/reference/analyses.html#lipid-z-positions-lipyphilic-analysis-z-positions",target:"_blank",rel:"noreferrer noopener",children:"Lipyphilic Z positions"})," "," using the most charged atom of each lipid residue as headgroups."]}),page:e.jsxs(e.Fragment,{children:["Thickness of the membrane of time meassured as distance between the most charged atoms of the lipids from of each leaflet.",e.jsx("br",{}),e.jsx("br",{}),"In the visualization we can see represented the local distorsion where thinning is displayed in red and thickning in blue, starting from white, with a gradient that reach a maximum at three times the standard deviation of the thickness over all the trajectory."]})},{id:"apl",header:"Area per lipid",body:e.jsxs(e.Fragment,{children:["Area per lipid (APL) analysis performed with the"," ",e.jsx("a",{href:"https://pythonhosted.org/fatslim/documentation/apl.html",target:"_blank",rel:"noreferrer noopener",children:"FATSLiM APL"})," "," tool. The analysis calculates the local area per lipid for each leaflet of the membrane using the most charged atom of each lipid residue as reference points."]}),page:e.jsxs(e.Fragment,{children:["This is the Area per Lipid analysis page.",e.jsx("br",{}),e.jsx("br",{}),"Two heatmaps are displayed showing the local area per lipid distribution for the upper and lower leaflets of the membrane. The area is calculated on a grid across the membrane plane (XY coordinates). The color scale represents deviations from the median APL value, where:",e.jsx("br",{}),"- Red indicates areas with smaller APL (compressed regions)",e.jsx("br",{}),"- White indicates areas close to the median APL",e.jsx("br",{}),"- Blue indicates areas with larger APL (expanded regions)",e.jsx("br",{}),e.jsx("br",{}),"The color scale range can be adjusted using the slider below the heatmaps, which controls how many standard deviations (σ) from the median are shown. A larger value will show more extreme variations while a smaller value will highlight subtle differences.",e.jsx("br",{}),e.jsx("br",{}),"Hover over any point in the heatmaps to see the exact coordinates and area per lipid value at that position. The units are in square Ångstroms (Å²)."]})},{id:"lipid-order",header:"Lipid order parameter",body:e.jsxs(e.Fragment,{children:["The order parameter analysis calculates the order parameter for lipid tails in the membrane. This parameter provides insights into the degree of order or disorder within the lipid bilayer. The analysis is performed for each lipid type present in the membrane, and the results are displayed as a function of the carbon position along the lipid tail.",e.jsx("br",{}),e.jsx("br",{}),"The order parameter is calculated for each frame in the trajectory, and the mean and standard deviation values are provided for each lipid tail. This analysis is powered by custom scripts developed with "," ",e.jsx("a",{href:"https://www.mdanalysis.org/",target:"_blank",rel:"noreferrer noopener",children:"MDAnalysis"})," ","."]}),page:e.jsxs(e.Fragment,{children:["This is the Order Parameter analysis page.",e.jsx("br",{}),e.jsx("br",{}),"The order parameter analysis calculates the order parameter for lipid tails in the membrane. This parameter provides insights into the degree of order or disorder within the lipid bilayer. The analysis is performed for each lipid type present in the membrane, and the results are displayed as a function of the carbon position along the lipid tail.",e.jsx("br",{}),e.jsx("br",{}),"The order parameter is calculated for each frame in the trajectory, and the mean and standard deviation values are provided for each lipid tail.",e.jsx("br",{}),e.jsx("br",{}),"The graph below shows the order parameter values for each carbon position along the lipid tails. The horizontal axis represents the carbon position, and the vertical axis represents the order parameter. The table below the graph provides the mean and standard deviation values for each lipid tail. Use the checkboxes to toggle the display of individual lipid tails in the graph.",e.jsx("br",{}),e.jsx("br",{}),"You can interact with the graph to select specific carbon positions and view the corresponding representations in the molecular viewer."]})},{id:"lipid-inter",header:"Lipid-protein interactions",body:e.jsxs(e.Fragment,{children:["The lipid-protein interactions analysis identifies and quantifies interactions between protein residues and membrane lipids throughout the trajectory. This analysis helps identify preferential binding spots on the protein surface and characterize lipid binding patterns.",e.jsx("br",{}),e.jsx("br",{}),"For each protein residue, the analysis calculates the frequency of interactions with different lipid types by counting the number of frames where any lipid atom comes within a 6 Å cutoff distance.",e.jsx("br",{}),e.jsx("br",{}),"This analysis is powered by custom scripts developed with "," ",e.jsx("a",{href:"https://www.mdanalysis.org/",target:"_blank",rel:"noreferrer noopener",children:"MDAnalysis"})," ","."]}),page:e.jsxs(e.Fragment,{children:["This is the Lipid-Protein Interactions analysis page.",e.jsx("br",{}),e.jsx("br",{}),"This visualization shows how membrane lipids interact with the protein throughout the trajectory. Select different lipid types using the tabs above to view their specific interaction patterns with the protein.",e.jsx("br",{}),e.jsx("br",{}),"The protein structure is colored according to the frequency of interactions with the selected lipid type. The color gradient ranges from white (no interaction) through orange to dark red (high interaction frequency), indicating how often each protein residue interacts with the selected lipid during the simulation.",e.jsx("br",{}),e.jsx("br",{}),"Protein residues are considered to interact with a lipid when any lipid atom comes within a 6 Å distance of the residue. The interaction frequency represents the proportion of analyzed frames where this interaction occurs.",e.jsx("br",{}),e.jsx("br",{}),"The selected lipid type is also displayed in the viewer with an orange licorice representation, allowing you to visualize its position relative to the protein. This helps identify binding sites and interpret the colored interaction patterns on the protein surface."]})}]},{id:"features",title:"Features",children:[{id:"browser",header:"Browser",body:e.jsxs(e.Fragment,{children:["Browser is useful to search a specific simulation when you know what you are looking for",e.jsx("br",{}),e.jsx("br",{}),"Browser searches the database by any total or partial coincidence with the accession number, simulation name, description, author or group names.",e.jsx("br",{}),e.jsx("br",{}),"In addition, internal accessions may be used to search a simulation. In this case the id must be whole, not partial."]}),text:"Use the browser to search a specific simulation by its accession number, name, description, author or group names. Any total or partial coincidence works."},{id:"overview",header:"Overview page",body:e.jsxs(e.Fragment,{children:["Data in this page is mostly provided by the simulation authors. Additional details about the original pdb structure are mined from the ",e.jsx(t,{name:"PDB web page",url:"https://www.rcsb.org/"}),"."]}),page:e.jsxs(e.Fragment,{children:["This is the overview page.",e.jsx("br",{}),e.jsx("br",{}),"Data in this page may include the name and description of the simulation, author and group names, type of simulation, program which carried the simulation and its version, original structure PDB data, ligand references to DrugBank and ChEMBL, contact details and TextLinks to the simulation sources, license and citation."]})},{id:"mordred-descriptors",header:"Mordred descriptors",body:e.jsx(e.Fragment,{children:"The Mordred descriptors provide detailed information about a molecule’s structure, properties, and behavior. They help translate chemical structures into numerical values, which are useful for tasks like drug discovery, property prediction, and machine learning in chemistry."}),page:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"The Mordred descriptors shown in the table represent numerical values that describe various structural and chemical features of the ligand molecules. These values are generated using different descriptor calculators, each capturing a specific aspect of molecular behavior."}),e.jsxs("p",{children:["The descriptors were calculated using ",e.jsx("strong",{children:"RDKit"})," in combination with the",e.jsx("strong",{children:" Mordred"})," library."]}),e.jsx("p",{children:"For this analysis, the following calculators were used:"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"ABCIndex"}),": Measures the branching of the molecule’s structure."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"AcidicGroupCount"})," (",e.jsx("code",{children:"nAcid"}),"): Counts acidic functional groups."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"BasicGroupCount"})," (",e.jsx("code",{children:"nBase"}),"): Counts basic functional groups."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"RingCount"})," (",e.jsx("code",{children:"nRing"}),", ",e.jsx("code",{children:"n3Ring"}),", ",e.jsx("code",{children:"n4Ring"}),"): Detects rings and their sizes."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Constitutional"}),": Basic properties like atom count and molecular weight."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"TopologicalCharge"}),": Shape, partial charges, and polarity indicators."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"HydrogenBond"}),": Hydrogen bond donors and acceptors."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Lipinski"}),": Evaluates drug-likeness (Lipinski’s Rule of Five)."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"FragmentComplexity"}),": Analyzes complex molecular substructures."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"PathCount"}),": Counts molecular paths of varying lengths."]})]})]})},{id:"morgan-fingerprint",header:"Morgan fingerprint",body:e.jsx("p",{children:"The Morgan fingerprint is a type of molecular fingerprint that encodes the structure of a molecule into a binary vector. It enables mapping of specific structural patterns within a defined bond radius, and is commonly used to represent molecular features for similarity searching and machine learning applications."}),page:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"The Morgan fingerprint is a widely used method to represent molecular structures as binary vectors, capturing circular atom environments within a certain radius. It is especially useful for tasks such as molecular similarity, clustering, and predictive modeling in cheminformatics."}),e.jsxs("p",{children:["In this project, the Morgan fingerprint was generated using ",e.jsx("strong",{children:"RDKit"})," with a radius of ",e.jsx("code",{children:"2"})," and vector sizes of ",e.jsx("code",{children:"1024"})," and ",e.jsx("code",{children:"2048"})," bits. The binary array encodes structural patterns around each atom, allowing for efficient comparison of molecular features."]}),e.jsxs("p",{children:["In addition to generating the fingerprint vector, we also extracted atom-level information using RDKit’s",e.jsx("code",{children:"AdditionalOutput"})," methods, which include:"]}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"AtomCounts"}),": Tracks how often each atom contributes to the fingerprint."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"AtomToBits"}),": Maps atoms to the fingerprint bits they influence."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"BitInfoMap"}),": Stores which atoms and radii contributed to each bit."]})]}),e.jsx("p",{children:"This information is useful for visualizing and interpreting which parts of a ligand are responsible for specific features in the fingerprint, and can be used for highlighting relevant atoms in molecular diagrams."})]})},{id:"trajectory",header:"Trajectory page",body:e.jsxs(e.Fragment,{children:["The trajectory displayed in the"," ",e.jsx(t,{name:"viewer",id:"ngl-viewer"})," is a subset of frames from the project main trajectory (25 frames by default). Loading all frames is not allowed for performance reasons.",e.jsx("br",{}),e.jsx("br",{}),"Predefined representation sets come from three different sources:",e.jsx("br",{}),"- Documented domains in the reference sequence (manually gathered from"," ",e.jsx(t,{name:"Uniprot",url:"https://www.uniprot.org/"}),")",e.jsx("br",{}),"- Each defined interacting agent (see"," ",e.jsx(t,{name:"data processing",id:"processing"}),")",e.jsx("br",{}),"- Custom sets defined by the simulation authors",e.jsx("br",{}),e.jsx("br",{}),"Some metadata values are mined from the topology and trajectory files while others are supplied by the authors.",e.jsx("br",{}),e.jsx("br",{}),"The protein functional analysis contains the families, domains, and sites, that an ",e.jsx(t,{name:"InterProScan",id:"interpro"})," ","analysis revealed for each of the chain sequences. This is a prediction that might be helpful to discover functions, or to find similar structures for example."]}),page:e.jsxs(e.Fragment,{children:["This is the trajectory page.",e.jsx("br",{}),e.jsx("br",{}),"The"," ",e.jsx("a",{href:"/help#/help#ngl-viewer",target:"_blank",rel:"noreferrer noopener",children:"viewer"})," ","displays the main simulation dinamically and interactively. Use the mouse inside the NGL window to move, rotate or zoom the camera. You can get topology data of any atom by placing the mouse over it. Also some controls are available under the NGL viewer in order to play/pause the trajectory, go fullscreen or change the viewer settings. Place the mouse over any button to show a summary title. Note that this is not the whole trajectory, but a small subset of frames picked along the trajectory. You can modify the number of frames to be loaded from the settings menu.",e.jsx("br",{}),e.jsx("br",{}),"Over the viewer there is a menu where each bubble will make the viewer show a predefined set of representations on click. This tool allows to highlight an important region in the structure (e.g. known domains). You may hold Control/Cmd key while clicking on a bubble in order to overlap up to 2 representation sets at the same time. Note that the overlapped set will always appear with the fill representation type and reduced opacity.",e.jsx("br",{}),e.jsx("br",{}),"Below the viewer there is the trajectory metadata menu. Click in the title to drop a table with metadata values. Hover any data field with the mouse to show a brief title.",e.jsx("br",{}),e.jsx("br",{}),"Below the metadata there is the protein functional analysis. Recognized families, domains, and sites are displayed. You can interact with this visualisation as such:",e.jsx("br",{}),e.jsx("strong",{children:"Hover over their representation"})," to see that some of them will have a corresponding page on the"," ",e.jsx("a",{href:"https://www.ebi.ac.uk/interpro/",target:"_blank",rel:"noreferrer noopener",children:"InterPro website"})," ","where you will be able to learn more about it.",e.jsx("br",{}),e.jsx("strong",{children:"Click on them"})," to see the corresponding sequence highlighted in the viewer above. Clicking on an other entity within the same chain will change the highlight to that other entity.",e.jsx("br",{}),e.jsx("strong",{children:"Click on an empty space"})," in this visualisation to remove the highlight for that chain.",e.jsx("br",{}),e.jsx("strong",{children:"Scroll over the visualisation"})," to zoom in or out of the chain sequence. Alternatively, you can also interact with the top navigation part (at the top of each visualisation) to zoom in and out or to move within the sequence."]})},{id:"ngl-viewer",header:"NGL viewer",body:e.jsxs(e.Fragment,{children:["NGL Viewer is a collection of tools for web-based molecular graphics.",e.jsx("br",{}),e.jsx("br",{}),"The ",i," implementation of NGL viewer is a dynamic component useful to represent molecular structures and trajectories which the user can interact with.",e.jsx("br",{}),e.jsx("br",{}),'This component may be integrated in the web page structure (e.g. in the "trajectory" sheet) or an independent pop-up window which is draggable and resizable. To do so, hold left click in the window borders and drag.',e.jsx("br",{}),e.jsx("br",{}),"Use the mouse inside the NGL window to move the camera (hold right click), rotate the camera around its focus (hold left click) or zoom the camera (mouse wheel). Hover any atom with the mouse to get extra topology data (e.g. atom type, residue number or chain id) or left click on any atom to make the camera focus on it.",e.jsx("br",{}),e.jsx("br",{}),"Also some controls ara available under the NGL viewer in order to change other parameters:",e.jsx("br",{}),e.jsx(a,{children:e.jsx(r,{icon:d})})," ",'(Only in pop-up) The "close" button is used to remove the whole NGL viewer pop-up window.',e.jsx("br",{}),e.jsx(a,{children:e.jsx(r,{icon:c})})," / ",e.jsx(a,{color:"disabled",children:e.jsx(r,{icon:p})})," ",'(Only in pop-up) The "lock" button is used to make the current NGL viewer pop-up window stay as it is. So when a new selection is requested a new NGL window is opened instead of updating the locked window.',e.jsx("br",{}),e.jsx(a,{children:e.jsx(r,{icon:m})}),", ",e.jsx(a,{children:e.jsx(r,{icon:u})})," ",'(Only with trajectory data) The "Previous frame" and "Next frame" buttons respectively are used to move through trajectory frames one by one.',e.jsx("br",{}),e.jsx(a,{children:e.jsx(r,{icon:g})})," / ",e.jsx(a,{children:e.jsx(r,{icon:b})})," ",'(Only with trajectory data) The "Play / Pause" button is used to start or stop the trajectory animation.',e.jsx("br",{}),e.jsx(a,{children:e.jsx(r,{icon:f})})," / ",e.jsx(a,{children:e.jsx(r,{icon:y})})," ",'The "Enter / Exit full screen" button is used to make the NGL window expand to full screen or compress back to its normal size. User can also press "Esc" key to exit the full screen mode.',e.jsx("br",{}),e.jsx(a,{children:e.jsx(r,{icon:j})})," ",'The "Settings" button opens a new panel inside the viewer which allows to change the display of the viewer and the representations themselves. The right part of the panel includes a list with all current representations. It is allowed to change the type, colour and opacity of each representation as well as adding new representations with custom atom selections. This panel includes some controls at the left side:',e.jsx("br",{}),'- The "Toggle spin" button'," ",e.jsx(a,{children:e.jsx(r,{icon:x})})," ","is used to make the camera slowly rotate around the y-axis.",e.jsx("br",{}),' - The "Center focus" button'," ",e.jsx(a,{children:e.jsx(r,{icon:k})})," ","is used to make the camera return to its original focus.",e.jsx("br",{}),'- (Only with trajectory data) The "Smooth interpolation" button'," ",e.jsx(a,{children:e.jsx(r,{icon:S})})," ","/"," ",e.jsx(a,{children:e.jsx(r,{icon:w})})," ","is used to smooth the jump between frames by adding extra frames in-between where the atom positions are interpolated.",e.jsx("br",{}),'- The "Invert background color" button'," ",e.jsx(a,{children:e.jsx(r,{icon:v})})," ","is used to switch background color between black and white.",e.jsx("br",{}),'- The "Orthographic / Perspective" button'," ",e.jsx(a,{children:e.jsx(r,{icon:C})})," ","/"," ",e.jsx(a,{children:e.jsx(r,{icon:T})})," ","is used to change the view mode between 2D projection (orthographic or isometric) and 3D projection (perspective).",e.jsx("br",{}),'- The "Speed" bar is used to set how fast is the trajectory animation.',e.jsx("br",{}),'- The "Frames" bar allows to set how many frames along the trajectory are loaded in the viewer.',e.jsx("br",{}),e.jsx("br",{}),"For more information about the original project, please check the oficial"," ",e.jsx("a",{href:"http://nglviewer.org/",target:"_blank",rel:"noreferrer noopener",children:"NGL viewer web page"}),"."]})}]},{id:"bibliography",title:"Bibliography",children:[{id:"chemfiles",header:"Chemfiles",body:e.jsx(e.Fragment,{children:"https://doi.org/10.5281/zenodo.3653157"})},{id:"cmip",header:"CMIP",body:e.jsx(e.Fragment,{children:"Gelpí, J.L., Kalko, S.G., Barril, X., Cirera, J., de la Cruz, X., Luque, F.J. and Orozco, M. (2001), Classical molecular interaction potentials: Improved setup procedure in molecular dynamics simulations of proteins. Proteins, 45: 428-437. https://doi.org/10.1002/prot.1159"})},{id:"compass",header:"ComPASS",body:e.jsx(e.Fragment,{children:"Bheemireddy S, González Alemán R, Bignon E, Karami Y. Communication pathway analysis within protein-nucleic acid complexes. bioRxiv, 2025. https://doi.org/10.1101/2025.02.14.638259"})},{id:"gromacs",header:"Gromacs",body:e.jsxs(e.Fragment,{children:["H. Bekker, H.J.C. Berendsen, E.J. Dijkstra, S. Achterop, R. van Drunen, D. van der Spoel, A. Sijbers, and H. Keegstra et al., “Gromacs: A parallel computer for molecular dynamics simulations”; pp. 252–256 in Physics computing 92. Edited by R.A. de Groot and J. Nadrchal. World Scientific, Singapore, 1993.",e.jsx("br",{}),e.jsx("br",{}),"H.J.C. Berendsen, D. van der Spoel, and R. van Drunen, “GROMACS: A message-passing parallel molecular dynamics implementation,” Comp. Phys. Comm., 91 43–56 (1995).",e.jsx("br",{}),e.jsx("br",{}),"E. Lindahl, B. Hess, and D. van der Spoel, “GROMACS 3.0: A package for molecular simulation and trajectory analysis,” J. Mol. Mod., 7 306–317 (2001).",e.jsx("br",{}),e.jsx("br",{}),"D. van der Spoel, E. Lindahl, B. Hess, G. Groenhof, A.E. Mark, and H.J.C. Berendsen, “GROMACS: Fast, Flexible and Free,” J. Comp. Chem., 26 1701–1718 (2005).",e.jsx("br",{}),e.jsx("br",{}),"B. Hess, C. Kutzner, D. van der Spoel, and E. Lindahl, “GROMACS 4: Algorithms for Highly Efficient, Load-Balanced, and Scalable Molecular Simulation,” J. Chem. Theory Comput., 4 [3] 435–447 (2008).",e.jsx("br",{}),e.jsx("br",{}),"S. Pronk, S. Páll, R. Schulz, P. Larsson, P. Bjelkmar, R. Apostolov, M.R. Shirts, and J.C. Smith et al., “GROMACS 4.5: A high-throughput and highly parallel open source molecular simulation toolkit,” Bioinformatics, 29 [7] 845–854 (2013).",e.jsx("br",{}),e.jsx("br",{}),"S. Páll, M.J. Abraham, C. Kutzner, B. Hess, and E. Lindahl, “Tackling exascale software challenges in molecular dynamics simulations with GROMACS”; pp. 3–27 in Solving software challenges for exascale. Edited by S. Markidis and E. Laure. Springer International Publishing Switzerland, London, 2015.",e.jsx("br",{}),e.jsx("br",{}),"M.J. Abraham, T. Murtola, R. Schulz, S. Páll, J.C. Smith, B. Hess, and E. Lindahl, “GROMACS: High performance molecular simulations through multi-level parallelism from laptops to supercomputers,” SoftwareX, 1–2 19–25 (2015)."]})},{id:"interpro",header:"InterPro",body:e.jsx(e.Fragment,{children:"Blum M, Chang H, Chuguransky S, Grego T, Kandasaamy S, Mitchell A, Nuka G, Paysan-Lafosse T, Qureshi M, Raj S, RichardsonL, Salazar GA, Williams L, Bork P, Bridge A, Gough J, Haft DH, Letunic I, Marchler-Bauer A, Mi H, Natale DA, Necci M, Orengo CA, Pandurangan AP, Rivoire C, Sigrist CJA, Sillitoe I, Thanki N, Thomas PD, Tosatto SCE, Wu CH, Bateman A and Finn RD The InterPro protein families and domains database: 20 years on. Nucleic Acids Research, Nov 2020, (doi: 10.1093/nar/gkaa977)"})},{id:"legolas",header:"LEGOLAS",body:e.jsx(e.Fragment,{children:"Darrows MY, Kodituwakku D, Xue J, Pickering I, Terrel NS, Roitberg AE. LEGOLAS: a Machine Learning method for rapid and accurate predictions of protein NMR chemical shifts. J. Chem. Theory Comput. 2025, 21, 8, 4266–4275. https://doi.org/10.1021/acs.jctc.5c00026"})},{id:"mdpocket",header:"MDpocket",body:e.jsx(e.Fragment,{children:"Peter Schmidtke, Axel Bidon-Chanal, F. Javier Luque, Xavier Barril, MDpocket: open-source cavity detection and characterization on molecular dynamics trajectories, Bioinformatics, Volume 27, Issue 23, 1 December 2011, Pages 3276–3285, https://doi.org/10.1093/bioinformatics/btr550"})},{id:"mdtraj",header:"MDtraj",body:e.jsx(e.Fragment,{children:"Robert T. McGibbon, Kyle A. Beauchamp, Matthew P. Harrigan, Christoph Klein, Jason M. Swails, Carlos X. Hernández, Christian R. Schwantes, Lee-Ping Wang, Thomas J. Lane, Vijay S. Pande, MDTraj: A Modern Open Library for the Analysis of Molecular Dynamics Trajectories, Biophysical journal, Volume 109, Issue 8, 20 October 2015, Pages 1528-1532, http://doi.org/10.1016/j.bpj.2015.08.015"})},{id:"pytraj",header:"PyTraj",body:e.jsx(e.Fragment,{children:"Software for Processing and Analysis of Molecular Dynamics Trajectory Data. Daniel R. Roe and Thomas E. Cheatham, III. Journal of Chemical Theory and Computation 2013 9 (7), 3084-3095"})},{id:"sklearn",header:"scikit-learn",body:e.jsx(e.Fragment,{children:"Scikit-learn: Machine Learning in Python, Pedregosa et al., JMLR 12, pp. 2825-2830, 2011"})},{id:"vmd",header:"VMD",body:e.jsx(e.Fragment,{children:'Humphrey, W., Dalke, A. and Schulten, K., "VMD - Visual Molecular Dynamics", J. Molec. Graphics, 1996, vol. 14, pp. 33-38.'})}]}];h.find(s=>s.id==="analyses").children.sort((s,n)=>s.header.localeCompare(n.header));const L=h.reduce((s,n)=>(s.push(n),n.children&&n.children.forEach(l=>s.push(l)),s),[]);export{L as a,h as d};
